text:
{
  "logline": "閉山した銅山の町・尾根野で、郵便配達員の佐伯スミは宛名のない三通の手紙を届けることを望むが、公式記録と町の記憶が食い違っていることに阻まれる。",
  "acts": [
    {
      "id": "setup",
      "chapters": [
        "ch01"
      ],
      "question": "宛先のないものは、郵便ではないのか。"
    },
    {
      "id": "turn",
      "chapters": [
        "ch02"
      ],
      "question": "記録と記憶のどちらを信じるのか。"
    },
    {
      "id": "close",
      "chapters": [
        "ch03"
      ],
      "question": "記録に残らない事実を、誰に渡すのか。"
    },
    {
      "id": "aftermath",
      "chapters": [
        "ch04"
      ],
      "question": "手渡された後の事実を、紙のどこに残すのか。"
    }
  ],
  "turns": [
    {
      "id": "t1",
      "chapter": "ch01",
      "choice_ja": "スミは焼却の日取りを決めるのをやめ、三通を自分の鞄に入れて町を歩き出す。",
      "point_of_no_return": "局の保管棚の外に手紙を出した時点で、もう棚には戻せない。"
    },
    {
      "id": "t2",
      "chapter": "ch02",
      "choice_ja": "スミは訂正を申し出ず、代わりに死者欄の頁の写しを取る手続きを選ぶ。",
      "point_of_no_return": "閲覧簿に自分の名前を書いたことで、誰が何を見たかが町に残る。"
    },
    {
      "id": "t3",
      "chapter": "ch03",
      "choice_ja": "スミは記録を直すのではなく、三通目を源じいに手渡す。",
      "point_of_no_return": "手渡した相手が読んだ時点で、手紙は事実になる。"
    },
    {
      "id": "t4",
      "chapter": "ch04",
      "choice_ja": "スミは沢渡の支所へ戻り、源じいの言葉をあおいの写しの欄外に聞き取りとして書き留めさせる。",
      "point_of_no_return": "写しの控えが支所の綴じ込みに入った時点で、差出人の名は公文書と並ぶ紙に残る。"
    }
  ],
  "subplots": [
    {
      "id": "ledger",
      "beats": [
        "起動: スミが閲覧簿に名前を書かされる",
        "干渉: あおいが切り取られた頁の写しを出す",
        "決着: あおいが注記の頁を新しく起こす"
      ],
      "converges": "第三章、注記の頁にスミが立ち会い、記録の外の事実が初めて紙に載る。"
    }
  ],
  "ending": {
    "kind": "open",
    "summary": "記録は閉じたままだ。スミは三通目を源じいに渡し、源じいは初めて見送った日のことを話す。あおいは注記の頁に自分とスミの名を書く。",
    "aftertaste_ja": "訂正されない記録の重さと、それでも手渡された一通の軽さ。"
  },
  "unresolved": [
    {
      "item": "一通目の手紙の宛先は最後まで分からない",
      "foreshadowing": "fs-001",
      "intentional": true
    },
    {
      "item": "死者欄が零のまま書かれた理由は、書いた本人がすでにいない",
      "foreshadowing": "fs-003",
      "intentional": true
    }
  ]
}
